#!/bin/sh
# wbox win32 L1 build script: cross-compiles blink -> wbox-linux.exe
# with a MinGW-w64 clang/gcc toolchain.
#
# Parameterized via environment:
#   WBOX_CC      compiler driver. Either a real compiler
#                (e.g. x86_64-w64-mingw32-gcc, clang --target=...) or
#                "zig" to use `python3 -m ziglang cc` (default fallback).
#   WBOX_TARGET  target triple        (default x86_64-windows-gnu)
#   WBOX_BUILD   build/output dir     (default <repo>/build-win32)
#   WBOX_JOBS    parallel jobs        (default nproc)
#   WBOX_JIT     1 = JIT (default), 0 = pure interpreter (-DDISABLE_JIT)
#
# Example (llvm-mingw):
#   WBOX_CC=/tmp/wbox5/llvm-mingw/bin/x86_64-w64-mingw32-clang sh build-mingw.sh
set -e
cd "$(dirname "$0")/.."          # -> vendor/blink
BLINK_DIR=$PWD
BUILD=${WBOX_BUILD:-$BLINK_DIR/build-win32}
TARGET=${WBOX_TARGET:-x86_64-windows-gnu}
JOBS=${WBOX_JOBS:-$(nproc 2>/dev/null || echo 4)}

if [ -n "$WBOX_CC" ]; then
  CC=$WBOX_CC
elif command -v x86_64-w64-mingw32-gcc >/dev/null 2>&1; then
  CC=x86_64-w64-mingw32-gcc
else
  CC="python3 -m ziglang cc -target $TARGET"
fi
echo "CC = $CC"

CFLAGS="-O2 -g0 -fno-ident -DNDEBUG -Wno-everything \
  -Iwin32/compat -Iwin32 -I. -Ithird_party/libz -include win32/config.h"

JIT=${WBOX_JIT:-1}
echo "WBOX_JIT = $JIT"

# version stamp: wbox release + git short hash + UTC build time, consumed
# by blink/blink.c's PrintVersion (wbox-linux.exe --version / -v).
WBOX_VERSION=${WBOX_VERSION:-1.0.0-rc1}
GIT_HASH=$(git rev-parse --short HEAD 2>/dev/null || echo nogit)
BUILD_TS=$(date -u +%Y-%m-%dT%H:%M:%SZ)
mkdir -p "$BUILD"
VERH="$BUILD/version.h"
{
  echo "/* generated by win32/build-mingw.sh - do not edit */"
  echo "#define WBOX_BUILD_VERSION \"$WBOX_VERSION+$GIT_HASH\""
  echo "#define WBOX_BUILD_TIMESTAMP \"$BUILD_TS\""
} >"$VERH"
echo "version = $WBOX_VERSION+$GIT_HASH ($BUILD_TS)"
# zlib is plain C and must NOT see our POSIX compat headers (io.h clashes).
ZCFLAGS="-O2 -g0 -fno-ident -DNDEBUG -Wno-everything -I. -Ithird_party/libz"

# All blink core sources except the blinkenlights TUI frontend and the
# oneoff test utility (both carry their own main()).
SRCS=$(ls blink/*.c | grep -v -e 'blink/blinkenlights.c' -e 'blink/oneoff.c' \
        -e 'blink/jit.c' -e 'blink/jitflush.c')
if [ "$JIT" = 1 ]; then
  SRCS="$SRCS blink/jit.c blink/jitflush.c"
else
  CFLAGS="$CFLAGS -DDISABLE_JIT"
fi
SRCS="$SRCS win32/w32mem.c win32/w32fd.c win32/w32proc.c win32/w32sig.c win32/w32stubs.c win32/w32sock.c win32/w32errno.c"
# feat/net: w32sock.c provides the real socket/epoll/termios symbols. The
# L1 stubs that used to live in w32stubs.c (renamed away via the former
# STUB_RENAMES hack) were deleted; w32stubs.c now compiles clean.
# zlib core only: gz*.c pull in <io.h> and blink only needs
# compress2/uncompress/compressBound.
ZSRCS=$(ls third_party/libz/*.c | grep -v '/gz')

mkdir -p "$BUILD/obj"
OBJLIST=$BUILD/objlist.txt

objfile() { echo "$BUILD/obj/$(echo "$1" | tr '/.' '__').o"; }

# 目标文件清单在**前台按序**生成：原来由各后台子 shell 并发 >> 追加，
# 顺序不稳定且存在交错风险。
#
# 路径形态很关键：MSYS2 只对 argv 做 POSIX→Windows 路径转换，**响应文件
# （@list）的内容不转**。native ld.exe 读到 /d/a/... 会把每个 .o 都报
# "cannot find"（编译其实已成功，因为 -c -o 走的是 argv）。故清单里的路径
# 在有 cygpath 时一律转成宿主原生形式；Linux/无 cygpath 环境原样输出。
CYGPATH=$(command -v cygpath 2>/dev/null || true)
: >"$OBJLIST"
for src in $SRCS $ZSRCS; do
  obj=$(objfile "$src")
  if [ -n "$CYGPATH" ]; then obj=$("$CYGPATH" -w "$obj"); fi
  echo "$obj" >>"$OBJLIST"
done

compile_one() {
  src=$1
  obj=$(objfile "$src")
  case $src in
    third_party/libz/*) $CC $ZCFLAGS -c "$src" -o "$obj" ;;
    blink/blink.c) $CC $CFLAGS -include "$VERH" -c "$src" -o "$obj" ;;
    *) $CC $CFLAGS -c "$src" -o "$obj" ;;
  esac
}
export CC CFLAGS ZCFLAGS BUILD VERH

# poor man's parallel build。注意 set -e 对后台任务无效、无参 wait 恒返回 0，
# 所以必须逐个 pid 收状态——否则编译失败会被静默咽掉，直到链接期才以
# "cannot find *.o" 的形式暴露，误导排查方向。
fails=0
pids=
reap() {
  for p in $pids; do
    wait "$p" || fails=$((fails + 1))
  done
  pids=
}
i=0
for src in $SRCS $ZSRCS; do
  compile_one "$src" &
  pids="$pids $!"
  i=$((i + 1))
  if [ $((i % JOBS)) -eq 0 ]; then reap; fi
done
reap
if [ "$fails" -ne 0 ]; then
  echo "build-mingw.sh: $fails 个源文件编译失败（详见上方编译器输出）" >&2
  exit 1
fi

echo "linking..."
$CC -O2 -o "$BUILD/wbox-linux.exe" @"$OBJLIST" -lws2_32 -lwinmm -lbcrypt
PRE=$(wc -c <"$BUILD/wbox-linux.exe")
# strip debug/symbol residue when a PE-capable strip is at hand (mingw
# gcc builds carry a symbol table; zig cc -g0 output is already
# symbol-free, where this is a verified no-op).
if command -v x86_64-w64-mingw32-strip >/dev/null 2>&1; then
  x86_64-w64-mingw32-strip "$BUILD/wbox-linux.exe"
elif command -v llvm-strip >/dev/null 2>&1; then
  llvm-strip "$BUILD/wbox-linux.exe"
fi
POST=$(wc -c <"$BUILD/wbox-linux.exe")
echo "size: $PRE -> $POST bytes (strip delta $((PRE - POST)))"
echo "built: $BUILD/wbox-linux.exe"
